 extra=dict(status=t('開放中','Open'),eligibilityTW=t('可申請（須符合下列條件）','Eligible subject to conditions'),verificationDate=D,featuredDate=D,featuredUntil='2026-11-11T00:00:00+08:00',reviewExpiresAt='2026-11-17T00:00:00+08:00',country=t('英國','United Kingdom'),level=t(*x['level']),funding=t(*x['funding']),deadline=t(*x['deadline']),officialUrl=x['official'],secondSourceUrl=x['second'],sourceName='Aston University' if x['key']=='aston' else 'Birmingham City University',sourceType=t('大學官方','University official'),taiwanNote=t(desc,de))
